import os
import torch
import random
import numpy as np


class Config:
    """
    Configuration class for the Siamese DeBERTa-v3-Base with Late-Stage Cross-Attention.
    """

    # ==========================================
    # Paths & Directories
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_6"
    SUBMISSION_DIR = "./submission"

    # Input Files (Generated by metadata script)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Output Files
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # Cache Directory for processed features
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")

    # ==========================================
    # Model Architecture
    # ==========================================
    MODEL_NAME = "microsoft/deberta-v3-base"
    MAX_LENGTH = 512
    HIDDEN_SIZE = 768
    NUM_CLASSES = 3  # winner_model_a, winner_model_b, winner_tie

    # Siamese & Cross-Attention Specifics
    # We use the hidden states from the last N layers of the backbone
    USE_LAST_N_LAYERS = 4

    # Cross-Attention Block Hyperparameters
    CROSS_ATTN_LAYERS = 2
    CROSS_ATTN_HEADS = 12
    DROPOUT_PROB = 0.1

    # ==========================================
    # Feature Engineering
    # ==========================================
    USE_SCALAR_FEATURES = True
    TARGET_COLS = ["winner_model_a", "winner_model_b", "winner_tie"]

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    SEED = 42
    NUM_EPOCHS = 3

    # Batch Size Strategy for A100 40GB
    # DeBERTa-Base (512 seq) consumes significant memory for activations.
    # BS=8 is safe per forward pass. Gradient accumulation achieves effective BS=32.
    TRAIN_BATCH_SIZE = 8
    VALID_BATCH_SIZE = 16
    ACCUMULATION_STEPS = 4

    # Optimization
    # Differential Learning Rates: Lower for backbone, higher for new heads
    LR_BACKBONE = 1e-5
    LR_HEAD = 1e-4
    WEIGHT_DECAY = 0.01
    MAX_GRAD_NORM = 1.0

    # Early Stopping
    PATIENCE = 2

    # Debugging / Development
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 1000  # Number of samples to use if DEBUG is True

    # ==========================================
    # Hardware & Environment
    # ==========================================
    NUM_WORKERS = 4
    DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    @staticmethod
    def setup_environment():
        """
        Initializes the environment:
        1. Creates necessary directories.
        2. Sets random seeds for reproducibility.
        3. Configures system environment variables.
        """
        # Create directories
        os.makedirs(Config.WORKING_DIR, exist_ok=True)
        os.makedirs(Config.CACHE_DIR, exist_ok=True)
        os.makedirs(Config.SUBMISSION_DIR, exist_ok=True)

        # Set fixed seeds
        seed = Config.SEED
        random.seed(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        if torch.cuda.is_available():
            torch.cuda.manual_seed_all(seed)

        # Ensure deterministic behavior
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False

        # Disable tokenizer parallelism to prevent deadlocks in DataLoaders
        os.environ["TOKENIZERS_PARALLELISM"] = "false"

        print(f"Environment setup complete. Device: {Config.DEVICE}")
        print(f"Working Directory: {Config.WORKING_DIR}")
